  'f164ac0c-cd2c-4efa-bb6d-2ef56db8d6db');
-- Backup tables are not for the API: no grants beyond the owner, RLS on with no policies.
ALTER TABLE public.audit_backup_questions_20261019 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_backup_passages_20261019 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.audit_backup_questions_20261019, public.audit_backup_passages_20261019 FROM anon, authenticated;

-- 1. Verified text fixes (each guarded on the old text, so a re-run is a no-op).
UPDATE public.passages SET text = replace(text, 'a otherwise comparable', 'an otherwise comparable')
  WHERE id = '8e7621cb-fb3d-4cb3-99cb-3727e606c834' AND text LIKE '%a otherwise comparable%';  -- expect 1 row
UPDATE public.passages SET text = replace(text, 'bears a instructive', 'bears an instructive')
  WHERE id = 'f164ac0c-cd2c-4efa-bb6d-2ef56db8d6db' AND text LIKE '%bears a instructive%';  -- expect 1 row
UPDATE public.questions SET text = replace(text, 'what does umami primarily detect', 'what do umami receptors primarily detect')
  WHERE id = '90f9f49d-ad3d-4db1-a9d8-faa608cc4046' AND text LIKE '%what does umami primarily detect%';  -- expect 1 row
UPDATE public.questions SET options = (
    SELECT jsonb_agg(jsonb_set(o, '{text}', to_jsonb(replace(o->>'text', 'more unifiedly', 'in a more unified way'))) ORDER BY n)
    FROM jsonb_array_elements(options) WITH ORDINALITY AS t(o, n))
  WHERE id = '08cd4551-1fb2-4108-9ab1-ff75db25f388' AND options::text LIKE '%more unifiedly%';  -- expect 1 row
UPDATE public.questions SET text = regexp_replace(text, '___ ([,;:.])', '___\1', 'g')
  WHERE type = 'sentence_completion' AND text ~ '___ [,;:.]' AND id IN (
